patch:
diff --git a/src-tauri/crates/ffmpeg_utils/src/vulkan_video.rs b/src-tauri/crates/ffmpeg_utils/src/vulkan_video.rs
index 5cf8b8ee..13a3575b 100644
--- a/src-tauri/crates/ffmpeg_utils/src/vulkan_video.rs
+++ b/src-tauri/crates/ffmpeg_utils/src/vulkan_video.rs
@@ -1029,7 +1029,7 @@ fn build_graph(
             // Both sources already use the output geometry and SDR BT.709 clock.
             // Disable linear-light blending/tone mapping and extra image effects
             // to match the existing nonlinear premultiplied-overlay contract.
-            c"inputs=2:format=nv12:colorspace=bt709:color_primaries=bt709:color_trc=bt709:range=tv:disable_linear=1:peak_detect=0:apply_dolbyvision=0:apply_filmgrain=0:deband=0:dithering=none:sigmoid=0"
+            c"inputs=2:format=rgba:colorspace=gbr:color_primaries=bt709:color_trc=bt709:range=pc:disable_linear=1:peak_detect=0:apply_dolbyvision=0:apply_filmgrain=0:deband=0:dithering=none:sigmoid=0"
         } else {
             c"format=nv12:colorspace=bt709:color_primaries=bt709:color_trc=bt709:range=tv"
         };
@@ -1052,7 +1052,21 @@ fn build_graph(
     } else {
         graph.get("gpu_in").unwrap().link(0, &mut placebo, 0);
     }
-    placebo.link(0, &mut sink, 0);
+    if base_pool.is_some() {
+        unsafe {
+            let filter = ffi::avfilter_get_by_name(c"libplacebo".as_ptr());
+            let context = ffi::avfilter_graph_alloc_filter(graph.as_mut_ptr(), filter, c"gpu_nv12".as_ptr());
+            if context.is_null() { return Err("Allocate final GPU NV12 conversion".into()); }
+            (*context).hw_device_ctx = ffi::av_buffer_ref(device.0.raw.0);
+            if (*context).hw_device_ctx.is_null() { return Err("Retain final GPU conversion device".into()); }
+            check(ffi::avfilter_init_str(context, c"format=nv12:colorspace=bt709:color_primaries=bt709:color_trc=bt709:range=tv:disable_linear=1:peak_detect=0:apply_dolbyvision=0:apply_filmgrain=0:deband=0:dithering=none:sigmoid=0".as_ptr()), "Initialize final GPU NV12 conversion")?;
+        }
+        let mut convert = graph.get("gpu_nv12").unwrap();
+        placebo.link(0, &mut convert, 0);
+        convert.link(0, &mut sink, 0);
+    } else {
+        placebo.link(0, &mut sink, 0);
+    }
     graph
         .validate()
         .map_err(|e| format!("Configure Vulkan GPU graph: {e}"))?;
